"""Original 2D paws remain grounded and ease into alternate swing.

Only expressions returned by the trusted choreography module are evaluated.
No external/user-supplied expressions, media, API or model dependencies.
"""
from __future__ import annotations

import math
import unittest

from automate_ytb.choreography import CHOREOGRAPHY_VERSION, leg_position


def evaluate_trusted(expression: str, t: float) -> float:
    """Numerically evaluate expressions generated by our own fixed gait profiles."""
    return float(eval(expression, {"__builtins__": {}},
                      {"t": t, "sin": math.sin, "max": max, "min": min, "pow": pow}))


class EasedPawGaitTests(unittest.TestCase):
    def test_plant_contact_is_world_locked_and_paws_alternate(self):
        self.assertIn("v10", CHOREOGRAPHY_VERSION)
        for action, frequency, reach, lift in (
            ("walk", 5.1, 12, 11), ("run", 10.2, 21, 20)
        ):
            left = leg_position(action, side="left")
            right = leg_position(action, side="right")
            for x, y in (left, right):
                self.assertIn("3-2*", x)
                self.assertNotIn("t*0.37", x + y)
                self.assertNotIn(";", x + y)
            planted_t = math.pi / (2 * frequency)
            swinging_t = 3 * math.pi / (2 * frequency)
            # Left planted and right swinging; phases then exchange.
            self.assertAlmostEqual(evaluate_trusted(left[0], planted_t), 248.0, places=4)
            self.assertAlmostEqual(evaluate_trusted(left[1], planted_t), 519.0, places=4)
            self.assertAlmostEqual(evaluate_trusted(right[0], planted_t), 366 + reach, places=3)
            self.assertAlmostEqual(evaluate_trusted(right[1], planted_t), 519 - lift, places=3)
            self.assertAlmostEqual(evaluate_trusted(left[0], swinging_t), 248 + reach, places=3)
            self.assertAlmostEqual(evaluate_trusted(right[0], swinging_t), 366.0, places=3)

    def test_toe_off_touchdown_and_swing_peak_are_continuous(self):
        for action, frequency in (("walk", 5.1), ("run", 10.2)):
            for side in ("left", "right"):
                expressions = leg_position(action, side=side)
                period = 2 * math.pi / frequency
                for boundary in (0.0, period / 2, period, period * 1.5):
                    for expr in expressions:
                        left = evaluate_trusted(expr, boundary - 0.0001)
                        right = evaluate_trusted(expr, boundary + 0.0001)
                        self.assertLess(abs(left - right), 0.01)
                # Swing and stance remain finite and within the original rig.
                for tick in range(120):
                    t = period * tick / 120
                    x, y = (evaluate_trusted(expr, t) for expr in expressions)
                    self.assertTrue(math.isfinite(x) and math.isfinite(y))
                    self.assertTrue(240 <= x <= 400)
                    self.assertTrue(490 <= y <= 530)

    def test_jump_does_not_inherit_paw_swing_profile(self):
        x, y = leg_position("jump", side="left")
        self.assertIn("mod(t,1.75)", y)
        self.assertNotIn("3-2*(max(0,-sin(", x)


if __name__ == "__main__":
    unittest.main()
